from huggingface_hub import hf_hub_download
import shutil, os
for d in ['/app/model_cache/xlm-roberta-base', '/app/merged_model']:
    try:
        p = hf_hub_download('FacebookAI/xlm-roberta-base', 'sentencepiece.bpe.model')
        shutil.copy(p, os.path.join(d, 'sentencepiece.bpe.model'))
        print('copied spm to', d)
    except Exception as e:
        print('spm fail', d, type(e).__name__, str(e)[:200])
# also make sure special_tokens_map.json exists in both
for d in ['/app/model_cache/xlm-roberta-base', '/app/merged_model']:
    try:
        p = hf_hub_download('FacebookAI/xlm-roberta-base', 'special_tokens_map.json')
        shutil.copy(p, os.path.join(d, 'special_tokens_map.json'))
        print('copied special_tokens_map to', d)
    except Exception as e:
        print('stm fail', d, type(e).__name__, str(e)[:200])
" 2>&1

